const $=s=>document.querySelector(s);let current=null;
async function api(path,data,extra={}){const r=await fetch('/api/orders/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...extra.headers},...(data?{body:extra.body||JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not update this order.');return d;}
function node(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;}
function button(text,action,parent,disabled=false){const b=node('button',text);b.disabled=disabled;b.onclick=async()=>{b.disabled=true;$('#message').textContent='Working…';try{await action();$('#message').textContent='Saved.';}catch(e){$('#message').textContent=e.message;}finally{b.disabled=false;}};parent.append(b);return b;}
async function load(){try{const d=await api('admin');$('#signin').hidden=true;$('#connections').hidden=false;$('#connections').replaceChildren(node('h2','Connections'),node('p',Object.entries(d.connections).map(([k,v])=>`${k}: ${v?'ready':'not connected / not enabled'}`).join(' · ')));$('#message').textContent=d.connections.payments?'Checkout is enabled. All books still need manual release.':'Payments are switched off. Saved books can be reviewed; no live printing is allowed.';$('#order-list').replaceChildren();if(!d.orders.length)$('#order-list').append(node('p','No saved orders yet. New books will appear here.'));for(const o of d.orders){const b=node('button',`${o.story.title} · ${o.label} · ${o.status}`,'secondary');b.onclick=()=>select(o.id);$('#order-list').append(b);}}catch(e){$('#message').textContent=e.message;$('#signin').hidden=false;}}
async function act(action,data={}){const r=await api(current.id+'/'+action,{revision:current.revision,...data});await select(current.id);return r;}
async function select(id){current=await api(id);const o=current,s=$('#selected');s.hidden=false;s.replaceChildren();const card=node('div',null,'card');s.append(card);card.append(node('p',o.id,'kicker'),node('h2',o.story.title),node('p',`${o.label} · £${(o.amount/100).toFixed(2)} · ${o.status} · ${o.paymentStatus} ${o.paymentMode||''}`),node('p',o.email),node('p',[o.recipient.name,...Object.values(o.recipient.address)].filter(Boolean).join(', ')));if(o.holdReason)card.append(node('p',o.holdReason,'notice warning'));button('Refresh order',()=>select(id),card);if(o.paymentStatus==='paid')button('Send / retry payment confirmation email',()=>act('notify-receipt'),card);if(o.status==='submitted')button('Send / retry print confirmation email',()=>act('notify-printed'),card);if(o.emailStatus)card.append(node('p',o.emailStatus.message));if(o.paymentProvider==='ziina'&&o.paymentStatus==='paid'){if(o.refund){card.append(node('p','Refund: '+o.refund.status+' · printing remains on hold'));button('Check refund status',()=>act('refund-status'),card);}else button('Refund full payment and hold book',async()=>{if(confirm('Refund the full £'+(o.amount/100).toFixed(2)+' and stop this book from printing?'))await act('refund',{confirm:true,amountPence:o.amount});},card,['submitting','supplier_unknown','submitted'].includes(o.status));}if(o.paymentProvider==='ziina'&&o.status==='awaiting_payment')button('Verify Ziina payment',()=>act('check-payment'),card);button('Get current printer quote',()=>act('quote'),card,['submitting','supplier_unknown','submitted'].includes(o.status));button('Show customer’s private link',async()=>{const d=await api(id+'/customer-link',{revision:current.revision});const a=node('a',d.url,'private-link');a.href=d.url;a.target='_blank';a.rel='noopener';card.append(a);},card);button('Put on hold',async()=>{const reason=prompt('Why does this book need attention?');if(reason!==null)await act('hold',{reason});},card,['submitting','supplier_unknown','submitted'].includes(o.status));if(o.quote)card.append(node('p',`Latest UK printer quote: £${(o.quote.totalPence/100).toFixed(2)} at ${o.quote.quotedAt}`,'notice'));
const paid=o.paymentStatus==='paid',canBuild=paid&&['awaiting_review','building','proof_ready','awaiting_approval'].includes(o.status);const art=node('div',null,'card');s.append(art);art.append(node('h2','1. Prepare the complete book'),node('p','Generate one illustration at a time. Each button makes a paid artwork request. Check likeness and scene consistency before making the PDF. The renderer keeps artwork at its native 300dpi size rather than stretching it. A4 requests larger images; inspect these carefully because high-resolution generation is experimental. A finished PDF can also be uploaded.'));
const images=node('div',null,'book-list');art.append(images);for(const [slot,label,key] of [['cover','Cover',o.art.cover],...o.art.scenes.map((k,i)=>[i,'Story '+(i+1),k])]){const item=node('div');if(key){const a=node('a');a.href=`/api/orders/${id}/file?file=${key}`;a.target='_blank';a.rel='noopener';const im=document.createElement('img');im.src=a.href;im.alt=label;a.append(im,node('span',label));item.append(a);}else item.append(node('p',label+' not drawn'));button(key?'Replace '+label:'Draw '+label,()=>act('illustrate',{page:slot,replace:!!key}),item,!canBuild);images.append(item);}button('Build PDF proof',()=>act('make-proof'),art,!canBuild||!o.art.cover||!o.art.scenes.every(Boolean));
const file=document.createElement('input');file.type='file';file.accept='application/pdf';file.setAttribute('aria-label','Upload a finished print PDF');file.disabled=!canBuild;art.append(node('p','Or upload an externally prepared 28-page print PDF in the selected size:'),file);button('Upload print PDF',async()=>{if(!file.files[0])throw new Error('Choose a PDF first.');const r=await fetch(`/api/orders/${id}/upload-proof`,{method:'POST',headers:{'Content-Type':'application/pdf','X-Order-Revision':String(current.revision)},body:file.files[0]});const d=await r.json();if(!r.ok)throw new Error(d.error);await select(id);},art,!canBuild);
const review=node('div',null,'card');s.append(review);review.append(node('h2','2. Check the exact proof'));if(o.proof){const a=node('a','Open PDF proof','button secondary');a.href=`/api/orders/${id}/file?proof=${o.proof.hash}`;a.target='_blank';a.rel='noopener';review.append(a);const iframe=document.createElement('iframe');iframe.src=a.href;iframe.title='Print proof to approve';review.append(iframe);review.append(node('pre',JSON.stringify(o.proof.preflight,null,2)));button('Email proof to customer',()=>act('notify-proof'),review,o.status!=='proof_ready');review.append(node('p',o.customerApproved?'Customer has approved this exact file.':'Waiting for customer approval. Printing is blocked.','notice'));if(o.emailStatus)review.append(node('p',o.emailStatus.message));}else review.append(node('p','A complete proof is required before approval.'));
const approve=node('div',null,'card');s.append(approve);approve.append(node('h2','3. Your final approval'));for(const [id,text] of [['pages','I checked every page, spelling, story sequence, covers and dedication.'],['quality','I checked image resolution, likeness, fonts and safe margins in this exact PDF.'],['address','I checked the chosen size and UK delivery address.']]){const label=node('label'),checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.id='check-'+id;label.append(checkbox,document.createTextNode(text));approve.append(label);}button('Approve for printing',()=>{if(!['pages','quality','address'].every(k=>$('#check-'+k).checked))throw new Error('Complete all three checks first.');return act('approve',{checkedPages:true,checkedQuality:true,checkedAddress:true,proofHash:o.proof?.hash});},approve,o.status!=='awaiting_approval');
const send=node('div',null,'card');s.append(send);send.append(node('h2','4. Release to Prodigi'),node('p','This is the only action that places a real print order. Payment and both approvals must be verified. A test payment can never release a book.'));const limit=document.createElement('input');limit.type='number';limit.min='0';limit.step='.01';limit.value=o.quote?(o.quote.totalPence/100).toFixed(2):'';limit.setAttribute('aria-label','Maximum total printer cost in pounds');send.append(node('label','Maximum printer charge, including UK shipping and printer tax (£)'),limit);button(o.status==='supplier_unknown'?'Reconcile / retry same printer order':'Send this approved book to Prodigi',async()=>{if(!confirm('Place one paid '+o.label+' print order, up to £'+limit.value+'?'))return;const checkedPayment=o.paymentProvider!=='ziina'||confirm('I have checked this payment in Ziina now: it is completed, with no refund or dispute.');if(!checkedPayment)return;await act('submit',{checkedPayment,confirm:true,proofHash:o.proof?.hash,maxCostPence:Math.round(Number(limit.value)*100)});},send,!['approved','supplier_unknown'].includes(o.status)||o.paymentMode!=='live');button('Refresh printer status and tracking',()=>act('refresh'),send,!o.supplierId);if(o.supplierStatus)send.append(node('pre',JSON.stringify(o.supplierStatus,null,2)));}
void load();
